    ('whaleBuy',      'ví cá mập mua vào'),
    ('whaleSell',     'ví cá mập bán ra'),
    ('scoreAbove',    'điểm vượt ngưỡng'),
    ('jumpUp',        'điểm tăng thêm'),
    ('liqDropPct',    'thanh khoản giảm'),
    ('holdDropPct',   'số holder giảm'),
    ('whaleOut',      'dòng tiền ví lớn chuyển sang rút'),
